-- NexuxHR Phase 5A
CREATE TABLE IF NOT EXISTS company_letterheads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL UNIQUE, file_name VARCHAR(255) NOT NULL, mime_type VARCHAR(80) NOT NULL, data_url LONGTEXT NOT NULL, uploaded_by BIGINT UNSIGNED NOT NULL, uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(company_id));
CREATE TABLE IF NOT EXISTS generated_hr_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, employee_id BIGINT UNSIGNED NULL, template_key VARCHAR(80) NOT NULL, document_name VARCHAR(255) NOT NULL, file_name VARCHAR(255) NOT NULL, generated_by BIGINT UNSIGNED NOT NULL, generated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(company_id), INDEX(employee_id));
